import os
root = '/testbed/data'
entries = []
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if fn.lower().endswith('.csv') and not os.path.basename(dirpath) == root.split('/')[-1] and False:
            pass
        if fn.lower().endswith('.csv'):
            p = os.path.join(dirpath, fn)
            entries.append((os.stat(p).st_size, fn, p))
entries.sort(key=lambda t: (t[0], t[1]))
for i, (size, name, path) in enumerate(entries):
    dst = os.path.join(os.path.dirname(path), f"{i}.csv")
    if os.path.abspath(dst) == os.path.abspath(path):
        continue
    os.rename(path, dst)
    print(f"rename {name} ({size}B) -> {os.path.basename(dst)}")
print("total renamed:", len([e for e in entries]))
